package com.saga.be.service.ai;
import com.saga.be.entity.ai.AiAcademicClassification; import com.saga.be.entity.enums.AiArtifactType; import com.saga.be.repository.AiAcademicClassificationRepository; import java.util.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Profile("!test") public class AiAcademicMappingService { private final AiAcademicClassificationRepository repo; public AiAcademicMappingService(AiAcademicClassificationRepository repo){this.repo=repo;} @Transactional(readOnly=true) public List<AiAcademicClassification> confirmed(UUID project,AiArtifactType type,UUID artifact,String revision){return repo.findAuthoritative(project,type,artifact,revision);} }
